"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6483],{75214:e=>{e.exports=JSON.parse('{"functions":[{"name":"collect","desc":"Buffers a signal\'s firings for later draining.\\n\\nArguments are stored flattened in one array rather than as a table per event,\\nwith a parallel array of argument counts to slice them back apart. Events\\nfire far more often than they are drained, so this avoids allocating a table\\nper firing. When the buffer empties, both cursors reset to the start so the\\narrays do not grow without bound.\\n\\nThe caller owns the returned connection and must disconnect it, normally in\\nthe system\'s cleanup function.\\n\\n```lua\\nlocal nextPlayer, connection = collect(Players.PlayerAdded)\\n-- inside the system:\\nfor player in nextPlayer do\\n\\t-- one iteration per firing since the last tick\\nend\\n```","params":[{"name":"signal","desc":"","lua_type":"Signal<T...>"}],"returns":[{"desc":"Drains one firing per call, returning its arguments; nothing when empty.","lua_type":"() -> any"},{"desc":"Disconnect this when the consumer goes away.","lua_type":"RBXScriptConnection"}],"function_type":"static","source":{"line":56,"path":"src/main/shared/utils/collect.luau"}}],"properties":[],"types":[{"name":"Signal","desc":"The subset of `RBXScriptSignal` this module needs, so it also accepts custom\\nsignal implementations.","fields":[{"name":"Connect","lua_type":"(self, callback) -> RBXScriptConnection","desc":""},{"name":"ConnectParallel","lua_type":"(self, callback) -> RBXScriptConnection","desc":""},{"name":"Once","lua_type":"(self, callback) -> RBXScriptConnection","desc":""},{"name":"Wait","lua_type":"(self) -> T...","desc":""}],"source":{"line":24,"path":"src/main/shared/utils/collect.luau"}}],"name":"collect","desc":"Buffers a Roblox signal so a system can drain the events that fired since its\\nlast tick.\\n\\nReacting inside a signal callback runs the work outside the scheduler, at an\\narbitrary point in the frame and outside the profiler\'s system boundaries.\\nBuffering moves that work back into the system that owns it.","tags":["shared-util"],"source":{"line":12,"path":"src/main/shared/utils/collect.luau"}}')}}]);